const invisible_places::water::WaterScenarioDefinition* FindWaterScenarioDefinition(
    const WaterWorkflowState& water,
    std::string_view scenarioId) {
    const auto scenarioIt = std::find_if(
        water.seepageScenarios.begin(),
        water.seepageScenarios.end(),
        [&](const auto& scenario) { return scenario.id == scenarioId; });
    return scenarioIt != water.seepageScenarios.end() ? &*scenarioIt : nullptr;
}

std::string WaterScenarioDisplayName(
    std::span<const invisible_places::water::WaterScenarioDefinition> definitions,
    const AnimationPath& animation) {
    if (animation.selectedWaterScenarioId.empty()) {
        return {};
    }
    const auto definitionIt = std::find_if(
        definitions.begin(),
        definitions.end(),
        [&](const auto& definition) {
            return definition.id == animation.selectedWaterScenarioId;
        });
    if (definitionIt != definitions.end() && !definitionIt->name.empty()) {
        return definitionIt->name;
    }
    const auto trackIt = std::find_if(
        animation.waterScenarioTracks.begin(),
        animation.waterScenarioTracks.end(),
        [&](const auto& track) {
            return track.scenarioId == animation.selectedWaterScenarioId;
        });
    if (trackIt != animation.waterScenarioTracks.end()) {
        if (!trackIt->scenarioName.empty()) {
            return trackIt->scenarioName;
        }
        if (!trackIt->fallbackScenario.name.empty()) {
            return trackIt->fallbackScenario.name;
        }
    }
    return animation.selectedWaterScenarioId;
}

std::string AnimationNameWithWaterScenario(
    std::string animationName,
    std::span<const invisible_places::water::WaterScenarioDefinition> definitions,
    const AnimationPath& animation) {
    const auto scenarioName = WaterScenarioDisplayName(definitions, animation);
    if (!scenarioName.empty()) {
        animationName += " - " + scenarioName;
    }
    return animationName;
}

std::optional<invisible_places::water::WaterScenarioState> ResolveActiveWaterScenarioState(
    const PreviewRuntimeState& runtimeState) {
    const auto* animation = runtimeState.animationPanel.currentPath.has_value()
                                ? &runtimeState.animationPanel.currentPath.value()
                                : nullptr;
    const std::string& scenarioId =
        animation != nullptr && !animation->selectedWaterScenarioId.empty()
            ? animation->selectedWaterScenarioId
            : runtimeState.water.selectedSeepageScenarioId;
    if (scenarioId.empty()) {
        return std::nullopt;
    }

    const auto* definition = FindWaterScenarioDefinition(runtimeState.water, scenarioId);
    const invisible_places::water::WaterScenarioTrack* track = nullptr;
    if (animation != nullptr) {
        const auto trackIt = std::find_if(
            animation->waterScenarioTracks.begin(),
            animation->waterScenarioTracks.end(),
            [&](const auto& candidate) { return candidate.scenarioId == scenarioId; });
        if (trackIt != animation->waterScenarioTracks.end()) {
            track = &*trackIt;
        }
    }

    const auto* fallbackDefinition = definition;
    if (fallbackDefinition == nullptr && track != nullptr &&
        !track->fallbackScenario.id.empty()) {
        fallbackDefinition = &track->fallbackScenario;
    }
    if (fallbackDefinition == nullptr) {
        return std::nullopt;
    }
    if (track != nullptr) {
        return invisible_places::water::EvaluateWaterScenarioTrack(
            *track,
            *fallbackDefinition,
            runtimeState.animationPanel.scrubAmount);
    }
    return fallbackDefinition->state;
}

struct WaterFrameState {
    float normalizedTime = 0.0F;
    float sampleTimeSeconds = 0.0F;
    float meshFlowMoisture = 0.0F;
    std::optional<invisible_places::water::WaterScenarioState> rawScenarioState;
    std::optional<invisible_places::water::WaterScenarioState> seepageScenarioState;
    std::vector<invisible_places::water::WaterSeepageNodeAnimationStateEntry> nodeStates;
};

WaterFrameState ResolveWaterFrameState(
    PreviewRuntimeState* runtimeState) {
    WaterFrameState result;
    if (runtimeState == nullptr) {
        return result;
    }
    result.normalizedTime = std::clamp(runtimeState->animationPanel.scrubAmount, 0.0F, 1.0F);
    result.rawScenarioState = ResolveActiveWaterScenarioState(*runtimeState);
    result.seepageScenarioState = result.rawScenarioState;
    if (result.rawScenarioState.has_value()) {
        result.meshFlowMoisture =
            std::clamp(result.rawScenarioState->rainLevel, 0.0F, 1.0F);
    }
    if (!runtimeState->animationPanel.currentPath.has_value()) {
        return result;
    }

    const auto& animation = runtimeState->animationPanel.currentPath.value();
    const float durationSeconds = std::max(
        1.0e-6F,
        invisible_places::camera::AnimationPathDurationSeconds(animation));
    result.sampleTimeSeconds = result.normalizedTime * durationSeconds;
    if (animation.selectedWaterScenarioId.empty()) {
        return result;
    }
    const auto trackIt = std::find_if(
        animation.waterScenarioTracks.begin(),
        animation.waterScenarioTracks.end(),
        [&](const auto& candidate) {
            return candidate.scenarioId == animation.selectedWaterScenarioId;
        });
    if (trackIt == animation.waterScenarioTracks.end()) {
        return result;
    }

    result.nodeStates = invisible_places::water::EvaluateWaterSeepageNodeAnimationTracks(
        *trackIt,
        result.normalizedTime);
    const auto* definition = FindWaterScenarioDefinition(
        runtimeState->water,
        animation.selectedWaterScenarioId);
    if (definition == nullptr && !trackIt->fallbackScenario.id.empty()) {
        definition = &trackIt->fallbackScenario;
    }
    if (definition == nullptr || !result.seepageScenarioState.has_value()) {
        return result;
    }

    const auto meshEnvelopeFingerprint =
        invisible_places::water::WaterMeshFlowRainEnvelopeFingerprint(
            *trackIt,
            *definition,
            durationSeconds);
    auto& meshEnvelope = runtimeState->animationPanel.meshFlowRainEnvelopeCache;
    if (meshEnvelope.fingerprint != meshEnvelopeFingerprint) {
        meshEnvelope = invisible_places::water::BuildWaterMeshFlowRainEnvelope(
            *trackIt,
            *definition,
            durationSeconds);
    }
    result.meshFlowMoisture =
        invisible_places::water::EvaluateWaterMeshFlowRainEnvelope(
            meshEnvelope,
            result.sampleTimeSeconds);

    const auto envelopeFingerprint =
        invisible_places::water::WaterSeepageRainEnvelopeFingerprint(
            *trackIt,
            *definition,
            durationSeconds);
    auto& envelope = runtimeState->animationPanel.seepageRainEnvelopeCache;
    if (envelope.fingerprint != envelopeFingerprint) {
        envelope = invisible_places::water::BuildWaterSeepageRainEnvelope(
            *trackIt,
            *definition,
            durationSeconds);
    }
    result.seepageScenarioState->rainLevel =
        invisible_places::water::EvaluateWaterSeepageRainEnvelope(
            envelope,
            result.sampleTimeSeconds);
    return result;
}

struct WaterFlowSourceActivityParameters {
    float maximumFlowStrength = 1.0F;
    float rainResponse = 0.0F;
    bool showTrail = true;
};

std::optional<WaterFlowSourceActivityParameters> ResolveWaterFlowSourceActivityParameters(
    const WaterWorkflowState& water,
    std::optional<std::uint32_t> sourceId) {
    if (!sourceId.has_value()) {
        return std::nullopt;
    }
    const auto emitterIt = std::find_if(
        water.emitters.begin(),
        water.emitters.end(),
        [&](const WaterEmitter& emitter) { return emitter.id == sourceId.value(); });
    if (emitterIt != water.emitters.end()) {
        return WaterFlowSourceActivityParameters{
            .maximumFlowStrength = emitterIt->maximumFlowStrength,
            .rainResponse = emitterIt->rainResponse,
            .showTrail = emitterIt->showTrail,
        };
    }
    const auto manualIt = std::find_if(
        water.manualFlowPaths.begin(),
        water.manualFlowPaths.end(),
        [&](const WaterManualFlowPathSource& source) { return source.id == sourceId.value(); });
    if (manualIt != water.manualFlowPaths.end()) {
        return WaterFlowSourceActivityParameters{
            .maximumFlowStrength = manualIt->maximumFlowStrength,
            .rainResponse = manualIt->rainResponse,
            .showTrail = manualIt->showTrail,
        };
    }
    return std::nullopt;
}

float ResolveWaterFlowSourceActivity(
    const WaterWorkflowState& water,
    std::optional<std::uint32_t> sourceId,
    const std::optional<invisible_places::water::WaterScenarioState>& scenarioState) {
    const auto parameters = ResolveWaterFlowSourceActivityParameters(water, sourceId);
    if (!parameters.has_value()) {
        return 1.0F;
    }
    return invisible_places::water::EffectiveWaterFlowActivity(
        scenarioState.value_or(invisible_places::water::WaterScenarioState{}),
        parameters->maximumFlowStrength,
        parameters->rainResponse,
        parameters->showTrail,
        water.showFlowTrails);
}

void ApplyWaterFlowSourceActivityToStyle(
    const WaterWorkflowState& water,
    const PreviewLayerSession& session,
    const std::optional<invisible_places::water::WaterScenarioState>& scenarioState,
    PointCloudStyleState* style) {
    if (style == nullptr || !session.waterFlowSourceId.has_value()) {
        return;
    }
    style->waterFlowActivity = ResolveWaterFlowSourceActivity(
        water,
        session.waterFlowSourceId,
        scenarioState);
}

std::string ActiveWaterScenarioDisplayName(const PreviewRuntimeState& runtimeState) {
    if (runtimeState.animationPanel.currentPath.has_value() &&
        !runtimeState.animationPanel.currentPath->selectedWaterScenarioId.empty()) {
        return WaterScenarioDisplayName(
            runtimeState.water.seepageScenarios,
            runtimeState.animationPanel.currentPath.value());
    }
    if (runtimeState.water.selectedSeepageScenarioId.empty()) {
        return {};
    }
    if (const auto* definition = FindWaterScenarioDefinition(
            runtimeState.water,
            runtimeState.water.selectedSeepageScenarioId);
        definition != nullptr && !definition->name.empty()) {
        return definition->name;
    }
    return runtimeState.water.selectedSeepageScenarioId;
}

