bool BakeWaterOverlayForActiveLayer(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport) {
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (!EnsureSceneAnalysisReadyForAction(
            runtimeState,
            DeferredSceneAnalysisAction::BakeWaterPath,
            "Bake Path")) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        runtimeState->errorMessage = "Please wait for the current layer load before generating water flow.";
        runtimeState->statusMessage.clear();
        return false;
    }
    CancelWaterFlowTrailBuildJob(&runtimeState->water);
    const auto supportIndex = ResolveWaterSupportSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->errorMessage =
            "Canonical analysis sources are still loading or unavailable; water flow cannot be baked from a sparse display cloud.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->water.activeSupportSessionIndex = supportIndex.value();

    auto& sourceSession = runtimeState->sessions[supportIndex.value()];
    if (sourceSession.offlinePointCloud == nullptr) {
        runtimeState->errorMessage = "The active water support scene is not available on CPU.";
        runtimeState->statusMessage.clear();
        return false;
    }
    const auto defaultSourceSettings = ActiveProfileDefaultWaterSourceSettings(runtimeState->water);
    const auto* supportCloud = EnsureWaterSupportCloud(runtimeState, sourceSession, defaultSourceSettings.path);
    if (supportCloud == nullptr || supportCloud->positions.empty()) {
        runtimeState->errorMessage = "No usable point-cloud support was available for water flow.";
        runtimeState->statusMessage.clear();
        return false;
    }

    runtimeState->errorMessage.clear();
    if (TryLoadWaterPathCacheForSupport(runtimeState, sourceSession) &&
        !runtimeState->water.pathCacheStale) {
        runtimeState->water.pathEditUndoHiddenBranchIds.clear();
        runtimeState->water.selectedPathBranchId.reset();
        runtimeState->water.hoveredPathBranchId.reset();
        if (!RefreshWaterOverlayFromAnchors(
                runtimeState,
                viewport,
                WaterOverlayRefreshPersistence::SavePathCache,
                WaterTrailBuildQuality::Final)) {
            return false;
        }
        runtimeState->water.pathDirty = false;
        runtimeState->water.dirtyEmitterIds.clear();
        std::string cacheSaveError;
        const bool cachePersisted = PersistSettledWaterPathCache(
            runtimeState,
            sourceSession,
            &cacheSaveError);
        runtimeState->statusMessage =
            "Reused cached water main paths with " +
            FormatPointCount(runtimeState->water.pathAnchors.points.size()) + " path anchors and " +
            FormatPointCount(runtimeState->water.pathCache.branches.size()) +
            " branches; updating source-local lanes and trails asynchronously.";
        if (!cachePersisted && !cacheSaveError.empty()) {
            runtimeState->statusMessage += " Flow cache was not persisted: " + cacheSaveError;
        }
        runtimeState->errorMessage.clear();
        return true;
    }

    const auto pathEmitters = WaterEmittersWithResolvedPathProfiles(runtimeState->water);
    if (std::none_of(
            pathEmitters.begin(),
            pathEmitters.end(),
            [](const WaterEmitter& emitter) { return emitter.status != WaterEmitterStatus::Disabled; })) {
        runtimeState->errorMessage = "No enabled water sources were available for path baking.";
        runtimeState->statusMessage.clear();
        return false;
    }

    runtimeState->statusMessage = "Baking water main paths...";
    const auto supportLayers = BuildWaterSourcePickSupportLayers(*runtimeState, sourceSession);
    const auto focusedSupportCloud = BuildFocusedWaterPathSupportCloud(
        *runtimeState,
        sourceSession,
        defaultSourceSettings.path,
        pathEmitters);
    const auto* bakeSupportCloud = focusedSupportCloud != nullptr ? focusedSupportCloud.get() : supportCloud;
    ++runtimeState->water.pathDiagnosticRebuildCounters.pathBakes;

    // Branch fingerprints let Bake Path keep unaffected sources while rebuilding moved,
    // added, deleted, or profile-changed emitters against the same support cloud.
    const auto bakeFingerprints = WaterEmitterBakeFingerprints(runtimeState->water, pathEmitters);
    const bool canReuseExistingCache =
        runtimeState->water.pathCacheLoaded &&
        !runtimeState->water.pathCache.branches.empty() &&
        WaterPathCacheMatchesSupport(
            *runtimeState,
            sourceSession,
            runtimeState->water.pathCache,
            defaultSourceSettings.path);
    const bool rebuildAllEmitters =
        !canReuseExistingCache ||
        (runtimeState->water.pathDirty && runtimeState->water.dirtyEmitterIds.empty());

    std::unordered_set<std::uint32_t> emittersToBakeIds;
    std::vector<WaterEmitter> emittersToBake;
    emittersToBake.reserve(pathEmitters.size());
    for (const auto& emitter : pathEmitters) {
        if (emitter.status == WaterEmitterStatus::Disabled) {
            continue;
        }
        const auto fingerprintIt = bakeFingerprints.find(emitter.id);
        const bool explicitlyDirty = runtimeState->water.dirtyEmitterIds.contains(emitter.id);
        const bool cachedBranchReusable =
            fingerprintIt != bakeFingerprints.end() &&
            CachedWaterEmitterBranchesReusable(
                runtimeState->water.pathCache,
                emitter.id,
                fingerprintIt->second);
        if (rebuildAllEmitters || explicitlyDirty || !cachedBranchReusable) {
            emittersToBakeIds.insert(emitter.id);
            emittersToBake.push_back(emitter);
        }
    }

    const std::size_t rebuiltEmitterCount = emittersToBake.size();
    std::size_t reusedBranchCount = 0U;
    if (canReuseExistingCache) {
        const auto previousCache = runtimeState->water.pathCache;
        const std::unordered_set<std::uint32_t> previousHiddenBranchIds{
            previousCache.hiddenBranchIds.begin(),
            previousCache.hiddenBranchIds.end()};
        auto rebuiltCache = emittersToBake.empty()
                                ? WaterPathCache{}
                                : invisible_places::water::GenerateWaterPathCache(
                                      *bakeSupportCloud,
                                      emittersToBake,
                                      defaultSourceSettings);
        StampWaterPathBranchFingerprints(&rebuiltCache, bakeFingerprints);

        WaterPathCache mergedCache = previousCache;
        mergedCache.branches.clear();
        mergedCache.hiddenBranchIds.clear();
        mergedCache.analysis.reset();
        for (const auto& branch : previousCache.branches) {
            const auto fingerprintIt = bakeFingerprints.find(branch.emitterId);
            if (fingerprintIt == bakeFingerprints.end() ||
                emittersToBakeIds.contains(branch.emitterId) ||
                branch.bakeFingerprint.empty() ||
                branch.bakeFingerprint != fingerprintIt->second) {
                continue;
            }
            if (previousHiddenBranchIds.contains(branch.id)) {
                mergedCache.hiddenBranchIds.push_back(branch.id);
            }
            mergedCache.branches.push_back(branch);
        }
        reusedBranchCount = mergedCache.branches.size();

        RemapWaterPathBranchIds(
            &rebuiltCache,
            MaxWaterPathBranchId(mergedCache.branches) + 1U);
        for (auto& branch : rebuiltCache.branches) {
            mergedCache.branches.push_back(std::move(branch));
        }
        if (rebuiltCache.diagnostics.estimatedPointSpacing > 0.0F) {
            mergedCache.diagnostics.estimatedPointSpacing = rebuiltCache.diagnostics.estimatedPointSpacing;
        }
        mergedCache.diagnostics.supportVoxelSize =
            std::max(mergedCache.diagnostics.supportVoxelSize, rebuiltCache.diagnostics.supportVoxelSize);
        mergedCache.diagnostics.maxBridgeDistance =
            std::max(mergedCache.diagnostics.maxBridgeDistance, rebuiltCache.diagnostics.maxBridgeDistance);
        if (rebuiltCache.diagnostics.pathSampleSpacing > 0.0F) {
            mergedCache.diagnostics.pathSampleSpacing =
                mergedCache.diagnostics.pathSampleSpacing <= 0.0F
                    ? rebuiltCache.diagnostics.pathSampleSpacing
                    : std::min(
                          mergedCache.diagnostics.pathSampleSpacing,
                          rebuiltCache.diagnostics.pathSampleSpacing);
        }
        mergedCache.diagnostics.branchSearchRadius =
            std::max(mergedCache.diagnostics.branchSearchRadius, rebuiltCache.diagnostics.branchSearchRadius);
        mergedCache.diagnostics.iterationCount =
            std::max(mergedCache.diagnostics.iterationCount, rebuiltCache.diagnostics.iterationCount);
        mergedCache.diagnostics.pilotTraceCount = rebuiltCache.diagnostics.pilotTraceCount;
        RefreshWaterPathCacheDiagnostics(
            &mergedCache,
            "Incremental water path bake reused " + FormatPointCount(reusedBranchCount) +
                " cached branches and rebuilt " + FormatPointCount(rebuiltEmitterCount) + " sources.");
        runtimeState->water.pathCache = std::move(mergedCache);
    } else {
        runtimeState->water.pathCache = invisible_places::water::GenerateWaterPathCache(
            *bakeSupportCloud,
            pathEmitters,
            defaultSourceSettings);
        StampWaterPathBranchFingerprints(&runtimeState->water.pathCache, bakeFingerprints);
    }

    runtimeState->water.pathCache.supportLayerPath = sourceSession.sourcePath;
    runtimeState->water.pathCache.supportSignature =
        CombinedWaterSupportSignature(*runtimeState, sourceSession, defaultSourceSettings.path);
    runtimeState->water.pathCache.emitterSettingsFingerprint = WaterEmitterSettingsFingerprint(*runtimeState);
    runtimeState->water.pathCache.requestedSettings = defaultSourceSettings.path;
    runtimeState->water.pathCache.tunedSettings = defaultSourceSettings.path;
    runtimeState->water.pathCache.stale = false;
    runtimeState->water.pathCacheLoaded = true;
    runtimeState->water.pathCacheStale = false;
    invisible_places::water::EnsureWaterPathAnalysis(&runtimeState->water.pathCache);
    EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
    runtimeState->water.pathEditUndoHiddenBranchIds.clear();
    runtimeState->water.selectedPathBranchId.reset();
    runtimeState->water.hoveredPathBranchId.reset();
    runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    if (runtimeState->water.pathCache.branches.empty() || runtimeState->water.pathAnchors.points.empty()) {
        runtimeState->water.pathDirty = true;
        runtimeState->errorMessage =
            "Water path bake found no supported downhill paths from " +
            FormatPointCount(pathEmitters.size()) + " sources using " +
            FormatPointCount(bakeSupportCloud->positions.size()) + " support samples over " +
            FormatPointCount(WaterSupportLayerPointCount(supportLayers)) + " raw role points from " +
            WaterSupportLayerSummary(supportLayers) + ".";
        runtimeState->statusMessage.clear();
        return false;
    }
    SaveWaterPathCacheForSupport(runtimeState, sourceSession);
    if (!QueueWaterFlowTrailRefresh(
            runtimeState,
            WaterOverlayRefreshPersistence::SavePathCache)) {
        runtimeState->errorMessage = "Water paths baked, but the asynchronous Flow update could not be queued.";
        runtimeState->statusMessage.clear();
        return false;
    }
    runtimeState->water.pathDirty = false;
    runtimeState->water.dirtyEmitterIds.clear();
    const std::string bakeAction =
        canReuseExistingCache
            ? "Updated water paths, rebuilt " + FormatPointCount(rebuiltEmitterCount) +
                  " sources, reused " + FormatPointCount(reusedBranchCount) +
                  " cached branches"
            : "Baked water main paths";
    runtimeState->statusMessage =
        bakeAction + " with " +
        FormatPointCount(runtimeState->water.pathAnchors.points.size()) + " path anchors across " +
        FormatPointCount(runtimeState->water.pathCache.branches.size()) +
        " branches; updating source-local lanes and trails asynchronously.";
    std::string cacheSaveError;
    if (!PersistSettledWaterPathCache(runtimeState, sourceSession, &cacheSaveError) &&
        !cacheSaveError.empty()) {
        runtimeState->statusMessage += " Flow cache was not persisted: " + cacheSaveError;
    }
    runtimeState->errorMessage.clear();
    return true;
}

bool RefreshWaterOverlayFromAnchors(
    PreviewRuntimeState* runtimeState,
    invisible_places::renderer::core::VulkanViewportShell* viewport,
    WaterOverlayRefreshPersistence persistence,
    WaterTrailBuildQuality quality) {
    (void)quality;
    if (runtimeState == nullptr || viewport == nullptr) {
        return false;
    }
    if (runtimeState->pendingLoad.has_value()) {
        return false;
    }
    const auto supportIndex = ResolveWaterRuntimeSessionIndex(*runtimeState);
    if (!supportIndex.has_value() || supportIndex.value() >= runtimeState->sessions.size()) {
        runtimeState->water.pathDirty = !runtimeState->water.emitters.empty();
        runtimeState->statusMessage = runtimeState->water.emitters.empty()
                                          ? "A loaded water support scene is required to build Flow trails."
                                          : "Water path bake required.";
        runtimeState->errorMessage.clear();
        return false;
    }
    if (runtimeState->water.pathCacheLoaded && !runtimeState->water.pathCache.branches.empty()) {
        invisible_places::water::EnsureWaterPathAnalysis(&runtimeState->water.pathCache);
        EnsureWaterFlowPathAnalysisSnapshot(&runtimeState->water);
        runtimeState->water.pathAnchors = WaterPathAnchorsFromCacheWithProfileSettings(*runtimeState);
    }
    const bool hasManualFlowPath = HasValidManualFlowPath(runtimeState->water);
    if (runtimeState->water.pathAnchors.points.empty() && !hasManualFlowPath) {
        runtimeState->water.pathDirty = !runtimeState->water.emitters.empty();
        runtimeState->statusMessage = runtimeState->water.emitters.empty()
                                          ? "No Flow sources are available."
                                          : "Water path bake required.";
        runtimeState->errorMessage.clear();
        return false;
    }
    if (persistence == WaterOverlayRefreshPersistence::SavePathCache && runtimeState->water.pathCacheLoaded) {
        SaveWaterPathCacheForSupport(runtimeState, runtimeState->sessions[supportIndex.value()]);
    }
    if (!QueueWaterFlowTrailRefresh(runtimeState, persistence)) {
        runtimeState->errorMessage = "Flow sources exist, but the asynchronous trail update could not be queued.";
        runtimeState->statusMessage.clear();
        return false;
    }
    if (runtimeState->water.emitters.empty()) {
        runtimeState->water.pathDirty = false;
        runtimeState->water.dirtyEmitterIds.clear();
    }
    runtimeState->statusMessage = "Updating source-local Flow lanes and trails asynchronously.";
    runtimeState->errorMessage.clear();
    return true;
}

